-- 1. 18 missions (catalog 62 to 79), every one a draft
insert into public.action_missions
  (id, campaign_id, title, description, domain, difficulty, base_points, proof_required, verification_mode,
   skills, capacity, status, starts_at, ends_at, kind, discovery_category)
select v.id, null, v.title, v.description, v.domain, v.difficulty, v.base_points, true, v.verification_mode,
       v.skills, null, 'draft', null, null, 'civic', v.discovery_category
  from (values
    ('728a63c6-8282-5cf3-91c6-90578935883d'::uuid, -- drawdown-deploy-micro-wind-turbines
     'Keep a week-long wind diary for your street',
     'For a week, check the wind near your home at the same times each day by watching flags, trees or a ribbon on your own balcony or fence, and compare what you see with the official weather forecast. At the end, write a few lines on whether the wind where you live is steady or gusty and why small turbines need good wind. Post a photo of your diary.',
     'research', 'explore', 1, 100, 'review', array['observation','data-analysis']::text[]),
    ('1bd34e77-5d56-532f-8989-77f1bde20630'::uuid, -- drawdown-deploy-nuclear-fusion
     'Explain fusion and fission in plain words',
     'Read a few reliable public sources, such as a national science agency or a university, about how nuclear fusion differs from the nuclear fission used in today''s power plants. Make a short post, poster or video that explains the difference in plain words, including what is still unknown, and list your sources. Post a link or photo.',
     'education', 'create', 2, 100, 'review', array['research','teaching']::text[]),
    ('9f545890-788e-5ce4-b6ce-042251b8d441'::uuid, -- drawdown-deploy-small-modular-nuclear-reactors
     'Check the public record on new reactor proposals',
     'Visit the public website of your country''s nuclear safety regulator, look for applications or plans for small modular reactors, and note any in your region. Write a short, neutral summary of what is proposed, where it stands, and any public meetings or comment periods. Post your summary with links.',
     'research', 'explore', 2, 100, 'review', array['research','policy-analysis']::text[]),
    ('f364102d-e11f-583a-8249-e8ce07615a75'::uuid, -- drawdown-deploy-advanced-geothermal-energy
     'Make a short video on next-generation geothermal',
     'Read about newer geothermal approaches, which aim to reach heat deep underground in places without natural hot springs, using reliable sources such as energy agencies and universities. Make a short video, slideshow or comic that explains the idea in plain words and what researchers are still testing. Post it with your sources listed.',
     'education', 'create', 2, 100, 'review', array['video','research']::text[]),
    ('1ba35152-acfa-5786-8eb7-015bfa01c232'::uuid, -- drawdown-deploy-methane-digesters
     'Find out if your wastewater plant makes biogas',
     'Look up the wastewater treatment plant that serves your area on its official website or annual report and see whether it uses digesters to turn sludge into biogas. If it isn''t clear, send a short question through the official contact form, or sign up for a public tour if one is offered. Post what you learned with links.',
     'research', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('3fb16043-b210-577e-b662-670cb9df0296'::uuid, -- drawdown-improve-district-heating-industry
     'Ask your council about reusing waste heat',
     'Factories, data centers and wastewater plants often give off waste heat that could be piped to nearby factories and other buildings. Check your city or regional energy or climate plan for any mention of waste heat or heat networks for industry, then send a polite question in your own words to a council member or planning office asking whether this has been studied locally. Post your question, any reply and links to what you read, with names and contact details hidden.',
     'advocacy', 'create', 2, 100, 'review', array['policy-analysis','writing']::text[]),
    ('29222f7a-28ca-54ba-970f-bbef5c525b0f'::uuid, -- drawdown-deploy-plastic-alternatives-bioplastics
     'Find out if your town takes compostable plastics',
     'Look at your local waste agency''s official recycling and compost rules to see whether compostable or plant-based plastics are accepted, and where they should go. Make a short, clear post or sign so neighbors don''t have to guess. Post a photo or link with the official source.',
     'education', 'create', 1, 100, 'review', array['research','writing']::text[]),
    ('940d2140-eb2f-58dc-b798-4ffc96fff671'::uuid, -- drawdown-improve-steel-production
     'Make a timeline of steelmaking, past to present',
     'Research how steel has been made, from early furnaces to today''s electric furnaces and newer methods that use hydrogen and clean power, using museums, libraries or reliable websites. If your region has a steel history, include it. Make a simple illustrated timeline and post a photo or link with your sources.',
     'research', 'create', 2, 100, 'review', array['research','design']::text[]),
    ('154bc628-8758-51ed-924a-1dd61ed2e171'::uuid, -- drawdown-reduce-airplane-contrails
     'Keep a week-long sky diary of plane trails',
     'For a week, look up at the same times each day and note the plane trails you see: do they fade quickly or spread out into thin clouds? Read a reliable source on why some trails linger, and add a short note. Post a photo of your diary or a few sky photos.',
     'research', 'explore', 1, 100, 'review', array['observation','photography']::text[]),
    ('4a35883c-a97e-5422-bd31-c5a6e4763554'::uuid, -- drawdown-mobilize-green-hydrogen-for-aviation-and-trucking
     'Weigh up hydrogen-powered trucks and planes',
     'Read reliable sources about using green hydrogen, made with renewable electricity, to power long-haul trucks and planes. Make a fair pros-and-cons chart in plain words, noting what is already working and what is still being tested. Post it with sources.',
     'research', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('12db7169-9d11-5a35-988c-d58c8d0a3c86'::uuid, -- drawdown-deploy-sustainable-aviation-fuel
     'Check one airline''s claims about cleaner jet fuel',
     'Find an airline''s public statements about sustainable aviation fuel, such as a press release or sustainability report. List what they say, then check reliable independent sources for what is known about that kind of fuel, and write a short, fair summary. Post it with links.',
     'research', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('0f2c4e86-82a9-5e77-9998-68ddb3c337fa'::uuid, -- drawdown-advance-cultivated-meat
     'Ask people what they think of cultivated meat',
     'Ask a few friends, relatives or classmates whether they would try meat grown from animal cells instead of from a slaughtered animal, and why. Keep answers anonymous and write a short summary of the range of views. Post your summary.',
     'research', 'explore', 1, 100, 'review', array['interviewing','writing']::text[]),
    ('22458ffa-9f2e-5a40-b72f-921a3a09b5a0'::uuid, -- drawdown-use-feed-additives
     'Explain cow burps and climate in a short video',
     'Cattle, sheep and goats release methane mostly by burping as they digest grass. Read reliable sources about the feed additives researchers are testing to cut that methane, then make a short video, comic or post that explains the idea and what is still being studied. Post it with sources.',
     'education', 'create', 1, 100, 'review', array['video','research']::text[]),
    ('a67c7c74-c7f6-55fc-b546-3ea4b959745a'::uuid, -- drawdown-improve-irrigation-water-use-efficiency
     'Track rainfall with a jar to guide your watering',
     'Set a straight-sided jar or can on the ground in an open spot and check it each day for a week to see how much rain has fallen. Use what you see to decide when your garden, balcony plants or community plot really need watering, and note each time you watered. Post a photo of your jar and your notes.',
     'research', 'explore', 1, 100, 'review', array['observation','gardening']::text[]),
    ('f9085849-2b32-5436-8bbe-99e52ed4e57b'::uuid, -- drawdown-deploy-leaf-protein-concentrates
     'Make a fact sheet on protein made from leaves',
     'Read reliable sources about leaf protein, which is protein taken from green leaves and crop leftovers for use in food and animal feed. Make a one-page fact sheet that explains how it is made and what researchers are still working out. Post a photo or link with your sources.',
     'education', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('f3e231f6-139d-504b-952e-b7deb39f9422'::uuid, -- drawdown-improve-ruminant-breeding
     'Watch and summarize a talk on cattle breeding',
     'Find a free public talk, webinar or lecture video from a university or agricultural agency about breeding cattle or sheep that produce less methane. Watch it and write a short summary in plain words of what you learned and what questions remain. Post your summary with a link to the talk.',
     'education', 'explore', 1, 100, 'review', array['research','writing']::text[]),
    ('ffc85842-a7a4-5629-a9c1-8b41a58eb5c1'::uuid, -- drawdown-deploy-seaweed-farming-for-food
     'Cook a dish with store-bought seaweed',
     'Buy a small pack of edible seaweed from a grocery store, such as nori or kelp, and make a simple dish with it. Share the recipe along with a few facts about how seaweed is farmed in the ocean, with your source. Post a photo of your dish and the recipe.',
     'creative', 'create', 1, 100, 'review', array['cooking','research']::text[]),
    ('93e0f0e8-0fe4-59f7-907f-05ac7287a250'::uuid, -- drawdown-deploy-alternative-grazing
     'Ask a farm advisor how local herds are grazed',
     'Contact your local agricultural advisory service, a university farm program or a grazing association with a short question: what grazing methods do local farmers use, such as moving animals often between fenced areas so the grass can rest? Write a plain-language summary of the answer or of their published guides. Post your summary with sources.',
     'research', 'explore', 2, 100, 'review', array['research','interviewing']::text[])
  ) as v(id, title, description, domain, discovery_category, difficulty, base_points, verification_mode, skills)
on conflict (id) do nothing;

